CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE curator(id uuid PRIMARY KEY, user_id text NOT NULL UNIQUE);
CREATE TABLE passkeys(id text PRIMARY KEY, curator_id uuid NOT NULL REFERENCES curator(id), public_key bytea NOT NULL, counter bigint NOT NULL CHECK(counter >= 0), transports jsonb NOT NULL, backed_up boolean NOT NULL);
CREATE TABLE ceremonies(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('register','login')), challenge text NOT NULL, expires_at timestamptz NOT NULL, consumed boolean NOT NULL DEFAULT false);
CREATE TABLE sessions(token_hash text PRIMARY KEY, curator_id uuid NOT NULL REFERENCES curator(id), csrf_hash text NOT NULL, authenticated_at timestamptz NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE rooms(id uuid PRIMARY KEY, title text NOT NULL, prompt text NOT NULL, public_jwk jsonb NOT NULL, key_thumbprint text NOT NULL, policy_digest text NOT NULL, network text NOT NULL CHECK(network IN ('localnet','esmeralda')), capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 128), state text NOT NULL CHECK(state IN ('creating','open','closing','closed','failed','unknown')), component text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE challenges(token_hash text PRIMARY KEY, room_id uuid NOT NULL REFERENCES rooms(id), expires_at timestamptz NOT NULL, consumed boolean NOT NULL DEFAULT false);
CREATE TABLE envelopes(id text PRIMARY KEY, room_id uuid NOT NULL REFERENCES rooms(id), jwe text NOT NULL, digest text NOT NULL, lookup_hash text NOT NULL UNIQUE, state text NOT NULL CHECK(state IN ('queued','submitted','confirmed','failed','unknown')), transaction_id text, epoch bigint, component_version bigint, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('create_room','anchor','close_room','reward')), entity_id text NOT NULL, state text NOT NULL CHECK(state IN ('queued','preparing','submitting','submitted','confirmed','failed','unknown')), transaction_id text, max_fee numeric(20,0), actual_fee numeric(20,0), attempts integer NOT NULL DEFAULT 0, error_code text, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,entity_id));
CREATE TABLE reward_quotes(id uuid PRIMARY KEY, envelope_id text NOT NULL REFERENCES envelopes(id), sealed_intent text NOT NULL, amount numeric(20,0) NOT NULL, max_fee numeric(20,0) NOT NULL, expires_at timestamptz NOT NULL, state text NOT NULL CHECK(state IN ('quoted','confirmed','expired')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rewards(id uuid PRIMARY KEY REFERENCES reward_quotes(id), envelope_id text NOT NULL REFERENCES envelopes(id), state text NOT NULL CHECK(state IN ('queued','submitting','submitted','confirmed','failed','unknown')), transaction_id text, max_fee numeric(20,0) NOT NULL, actual_fee numeric(20,0), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_reward_per_envelope ON rewards(envelope_id) WHERE state <> 'failed';
CREATE TABLE rate_limits(bucket text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE audit(id bigserial PRIMARY KEY, event text NOT NULL, entity_id text, code text, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
